'use strict';

function createRateHandler(rateTable) {
  if (!rateTable || typeof rateTable !== 'object' || Array.isArray(rateTable) ||
      Object.getPrototypeOf(rateTable) !== Object.prototype) {
    throw new TypeError('invalid rate table');
  }

  const rates = Object.create(null);
  for (const key of Object.keys(rateTable)) {
    const value = rateTable[key];
    if (key.length === 0 || typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new TypeError('invalid rate');
    }
    rates[key] = value;
  }

  return function handle(request) {
    if (!request || typeof request !== 'object' || request.method !== 'GET') {
      return { status: 405, body: { error: 'Method not allowed' } };
    }

    const id = request.params && request.params.productId;
    if (typeof id !== 'string' || id.length === 0) {
      return { status: 400, body: { error: 'Invalid product ID' } };
    }
    if (!rates[id]) {
      return { status: 404, body: { error: 'Product not found' } };
    }
    return { status: 200, body: { productId: id, rate: rates[id] } };
  };
}

module.exports = { createRateHandler };

