'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['createRateHandler']);
const { createRateHandler } = api;

for (const bad of [null, [], { '': 1 }, { a: -1 }, { a: Infinity }, { a: NaN }, { a: '1' }]) {
  assert.throws(() => createRateHandler(bad), TypeError);
}
const inherited = { inherited: 99 };
const table = Object.assign(Object.create(inherited), { free: 0, standard: 12.5 });
assert.throws(() => createRateHandler(table), TypeError);

const rates = { free: 0, standard: 12.5 };
const handle = createRateHandler(rates);
rates.free = 100;
rates.standard = 999;
rates.later = 3;

assert.deepEqual(handle({ method: 'GET', params: { productId: 'free' } }), {
  status: 200, body: { productId: 'free', rate: 0 }
});
assert.deepEqual(handle({ method: 'GET', params: { productId: 'standard' } }), {
  status: 200, body: { productId: 'standard', rate: 12.5 }
});
assert.deepEqual(handle({ method: 'GET', params: { productId: 'later' } }), {
  status: 404, body: { error: 'Product not found' }
});
assert.deepEqual(handle({ method: 'GET', params: { productId: 'missing' } }), {
  status: 404, body: { error: 'Product not found' }
});

for (const request of [
  { method: 'GET' },
  { method: 'GET', params: null },
  { method: 'GET', params: {} },
  { method: 'GET', params: { productId: '' } },
  { method: 'GET', params: { productId: 4 } }
]) {
  assert.deepEqual(handle(request), { status: 400, body: { error: 'Invalid product ID' } });
}
assert.deepEqual(handle({ method: 'POST', params: { productId: 'free' } }), {
  status: 405, body: { error: 'Method not allowed' }
});
assert.deepEqual(handle({ method: 'DELETE' }), {
  status: 405, body: { error: 'Method not allowed' }
});

const request = { method: 'GET', params: { productId: 'standard' } };
const responseOne = handle(request);
responseOne.status = 500;
responseOne.body.rate = -1;
const responseTwo = handle(request);
assert.deepEqual(responseTwo, { status: 200, body: { productId: 'standard', rate: 12.5 } });
assert.deepEqual(request, { method: 'GET', params: { productId: 'standard' } });
assert.notStrictEqual(responseOne, responseTwo);
assert.notStrictEqual(responseOne.body, responseTwo.body);

